{
  "name": "索雷博APT运动与压电控制器",
  "name_en": "Thorlabs APT Motion and Piezo Controller",
  "manufacturer": "Thorlabs",
  "description": "基于APT通信协议的索雷博多通道硬件控制器，用于驱动电机位移台、旋转台、压电台和压电惯性执行器等运动设备。可进行设备识别、通道管理、回零、绝对与相对运动、点动运动，以及位置和控制参数读取与设置。",
  "description_en": "A Thorlabs multi-channel hardware controller using the APT communication protocol to drive motion devices such as motorized stages, rotation stages, piezo stages, and piezo inertia actuators. It supports device identification, channel management, homing, absolute and relative moves, jog motion, and reading or setting position and control parameters.",
  "tag_hints": [
    "APT protocol",
    "motion control",
    "piezo actuation",
    "motorized stage",
    "multi-channel controller",
    "homing",
    "position control"
  ],
  "actions": [
    {
      "action_name": "auto-identify",
      "description": "使控制器指示灯闪烁以识别设备。",
      "description_en": "Blink the controller indicator so the device can be identified."
    },
    {
      "action_name": "auto-n_channels",
      "description": "获取/设置通道数量。",
      "description_en": "Get/set the number of channels."
    },
    {
      "action_name": "auto-serial_number",
      "description": "获取序列号。",
      "description_en": "Get the serial number."
    },
    {
      "action_name": "auto-model_number",
      "description": "获取型号编号。",
      "description_en": "Get the model number."
    },
    {
      "action_name": "auto-name",
      "description": "获取控制器名称。",
      "description_en": "Get the controller name."
    },
    {
      "action_name": "auto-channel",
      "description": "获取通道对象列表。",
      "description_en": "Get the list of channel objects."
    },
    {
      "action_name": "auto-destination",
      "description": "获取目标地址。",
      "description_en": "Get the destination address."
    },
    {
      "action_name": "auto-led_intensity",
      "description": "获取/设置LED亮度。",
      "description_en": "Get/set the LED intensity."
    },
    {
      "action_name": "auto-enabled_multi",
      "description": "获取/设置多通道使能状态。",
      "description_en": "Get/set the multi-channel enable state."
    },
    {
      "action_name": "auto-enabled",
      "description": "获取/设置使能状态。",
      "description_en": "Get/set the enabled state."
    },
    {
      "action_name": "auto-max_travel",
      "description": "获取/设置最大行程。",
      "description_en": "Get/set the maximum travel."
    },
    {
      "action_name": "auto-drive_op_parameters",
      "description": "获取/设置驱动运行参数。",
      "description_en": "Get/set the drive operating parameters."
    },
    {
      "action_name": "auto-enabled_single",
      "description": "获取/设置单通道使能状态。",
      "description_en": "Get/set the single-channel enable state."
    },
    {
      "action_name": "auto-jog_parameters",
      "description": "获取/设置点动参数。",
      "description_en": "Get/set the jog parameters."
    },
    {
      "action_name": "auto-position_count",
      "description": "获取位置计数值。",
      "description_en": "Get the position count."
    },
    {
      "action_name": "auto-move_abs",
      "description": "移动到绝对计数位置。",
      "description_en": "Move to an absolute count position."
    },
    {
      "action_name": "auto-move_jog",
      "description": "执行点动运动。",
      "description_en": "Perform a jog move."
    },
    {
      "action_name": "auto-move_jog_stop",
      "description": "停止点动运动。",
      "description_en": "Stop jog motion."
    },
    {
      "action_name": "auto-position_control_closed",
      "description": "获取/设置闭环位置控制状态。",
      "description_en": "Get/set the closed-loop position control state."
    },
    {
      "action_name": "auto-change_position_control_mode",
      "description": "切换位置控制模式。",
      "description_en": "Change the position control mode."
    },
    {
      "action_name": "auto-output_position",
      "description": "获取/设置输出位置。",
      "description_en": "Get/set the output position."
    },
    {
      "action_name": "auto-motion_timeout",
      "description": "获取/设置运动超时时间。",
      "description_en": "Get/set the motion timeout."
    },
    {
      "action_name": "auto-set_scale",
      "description": "定义运动刻度转换。",
      "description_en": "Define the motion scale conversion."
    },
    {
      "action_name": "auto-motor_model",
      "description": "获取/设置电机或平台型号。",
      "description_en": "Get/set the motor or stage model."
    },
    {
      "action_name": "auto-backlash_correction",
      "description": "获取/设置反向间隙补偿。",
      "description_en": "Get/set the backlash correction."
    },
    {
      "action_name": "auto-home_parameters",
      "description": "获取/设置回零参数。",
      "description_en": "Get/set the homing parameters."
    },
    {
      "action_name": "auto-status_bits",
      "description": "获取状态位。",
      "description_en": "Get the status bits."
    },
    {
      "action_name": "auto-position",
      "description": "获取当前位置。",
      "description_en": "Get the current position."
    },
    {
      "action_name": "auto-position_encoder",
      "description": "获取编码器位置。",
      "description_en": "Get the encoder position."
    },
    {
      "action_name": "auto-go_home",
      "description": "执行回零。",
      "description_en": "Home the axis or stage."
    },
    {
      "action_name": "auto-move",
      "description": "执行绝对或相对移动。",
      "description_en": "Move to an absolute or relative position."
    }
  ]
}

